/* =====================================================================
   Role icons stored as base64 in the database  —  2026-11-26
   Target DB : GWT_HIS_API (NEW HIS)
   Re-runnable: yes (IF NOT EXISTS / CREATE OR ALTER)

   Objects
     1. TABLE      dbo.RoleIconMaster    (new: 27 icons, PNG as base64)
     2. COLUMN     dbo.RoleMaster.RoleIconId (new) - filled from the old ImagePath file name
                   (unknown / empty path -> Avatar); then RoleMaster.ImagePath is DROPPED
     3. PROCEDURE  dbo.S_GetRoleIconList (new, all icons, for the Redis cache "_RoleIconMaster_All")
     4. PROCEDURE  dbo.IU_RoleMaster     (@imagePath replaced by @roleIconId)
     5. PROCEDURE  dbo.S_GetRoleList     (ImagePath replaced by RoleIconId)
     6. PROCEDURE  dbo.S_GetUserRoles    (ImagePath replaced by RoleIconId)
     7. DATA       dbo.PageConfigMaster 'roleMaster': grid card picture key imagePath -> roleIcon
     8. COLUMN     dbo.RoleMaster.FaIconId DROPPED (role FontAwesome icon, shown nowhere since the
                   image icons; IU_RoleMaster / S_GetRoleList / S_GetUserRoles no longer use it)

   Why: role icons were PNG files in the frontend (public/assets/RoleIcon) and RoleMaster.ImagePath
   held a URL that broke whenever the build path changed. The API now sends each role's icon as a
   base64 data URL read from the Redis cache.

   Run together with the API and frontend of the same date (the old API reads ImagePath).
   After running: restart the API, or clear the Redis keys _RoleMaster_All, _RoleIconMaster_All and _PageConfig_All.
   ===================================================================== */
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

/* 1. icon table */
IF OBJECT_ID('dbo.RoleIconMaster', 'U') IS NULL
BEGIN
    CREATE TABLE dbo.RoleIconMaster
    (
        RoleIconId  int IDENTITY(1,1) NOT NULL,
        IconName    nvarchar(100)     NOT NULL,
        MimeType    nvarchar(50)      NOT NULL CONSTRAINT DF_RoleIconMaster_MimeType DEFAULT (N'image/png'),
        IconBase64  nvarchar(max)     NOT NULL,
        IsActive    int               NOT NULL CONSTRAINT DF_RoleIconMaster_IsActive DEFAULT (1),
        CreatedOn   datetime          NOT NULL CONSTRAINT DF_RoleIconMaster_CreatedOn DEFAULT (GETDATE()),
        CONSTRAINT PK_RoleIconMaster PRIMARY KEY CLUSTERED (RoleIconId),
        CONSTRAINT UQ_RoleIconMaster_IconName UNIQUE (IconName)
    );
END
GO

IF COL_LENGTH('dbo.RoleMaster', 'RoleIconId') IS NULL
    ALTER TABLE dbo.RoleMaster ADD RoleIconId int NULL;
GO

/* 2. seed the icons and link every role (FileName is only used for this one-time link) */
IF OBJECT_ID('tempdb..#RoleIconSeed') IS NOT NULL DROP TABLE #RoleIconSeed;
CREATE TABLE #RoleIconSeed (IconName nvarchar(100), FileName nvarchar(100), MimeType nvarchar(50), IconBase64 nvarchar(max));
