    (N'Blood Bank', N'bloodbank.png', N'image/png', N''),
    (N'Camp', N'camp.png', N'image/png', N''),
    (N'Canteen', N'canteen.png', N'image/png', N''),
    (N'Cardiology', N'cardiology.png', N'image/png', N''),
    (N'CT Scan', N'ct-scan.png', N'image/png', N''),
    (N'Day Care', N'daycare.png', N'image/png', N''),
    (N'Dialysis', N'dialysis.png', N'image/png', N''),
    (N'Emergency', N'emergency.png', N'image/png', N''),
    (N'Expense Management', N'expense-management.png', N'image/png', N''),
    (N'Front Office', N'frontOffice.png', N'image/png', N''),
