INSERT INTO dbo.RoleIconMaster (IconName, MimeType, IconBase64)
SELECT s.IconName, s.MimeType, s.IconBase64
FROM #RoleIconSeed s
WHERE NOT EXISTS (SELECT 1 FROM dbo.RoleIconMaster r WHERE r.IconName = s.IconName);

-- link each role to the icon its old URL ends with (dynamic only because the column may already be gone)
IF COL_LENGTH('dbo.RoleMaster', 'ImagePath') IS NOT NULL
    EXEC (N'UPDATE rm SET rm.RoleIconId = ri.RoleIconId
            FROM dbo.RoleMaster rm
            INNER JOIN #RoleIconSeed s
                ON rm.ImagePath LIKE N''%/'' + s.FileName OR rm.ImagePath LIKE N''%/'' + s.FileName + N''?%''
            INNER JOIN dbo.RoleIconMaster ri ON ri.IconName = s.IconName
            WHERE rm.RoleIconId IS NULL;');

-- roles without a known icon get Avatar (the old default)
UPDATE dbo.RoleMaster
SET RoleIconId = (SELECT RoleIconId FROM dbo.RoleIconMaster WHERE IconName = N'Avatar')
WHERE RoleIconId IS NULL;

DROP TABLE #RoleIconSeed;
GO

/* old URL column is no longer used */
IF COL_LENGTH('dbo.RoleMaster', 'ImagePath') IS NOT NULL
    ALTER TABLE dbo.RoleMaster DROP COLUMN ImagePath;
GO

/* 3. icon list (cached by the API as _RoleIconMaster_All) */
CREATE OR ALTER PROCEDURE dbo.S_GetRoleIconList
AS
BEGIN
    SET NOCOUNT ON;
    SELECT RoleIconId, IconName, MimeType, IconBase64, IsActive
    FROM dbo.RoleIconMaster
    ORDER BY IconName;
END
GO

/* 4. role save: @imagePath -> @roleIconId */
CREATE OR ALTER PROCEDURE dbo.IU_RoleMaster
(
    @hospId     int,
    @roleId     int,
    @roleName   nvarchar(256),
    @roleIconId int,
    @isActive   int,
    @userId     int,
    @IpAddress  nvarchar(20),
    @Result     int = NULL OUTPUT
)
AS
BEGIN
    IF EXISTS (SELECT 1 FROM dbo.RoleMaster WHERE RoleName = @roleName AND RoleId <> @roleId)
    BEGIN
        SET @Result = -1;
    END
    ELSE IF (@roleId = 0)
    BEGIN
        INSERT INTO dbo.RoleMaster (HospId, RoleName, RoleIconId, IsActive, CreatedBy, IpAddress)
        VALUES (@hospId, @roleName, @roleIconId, @isActive, @userId, @IpAddress);

        SET @Result = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        UPDATE dbo.RoleMaster
        SET HospId = @hospId,
            RoleName = @roleName,
            RoleIconId = @roleIconId,
            IsActive = @isActive,
            LastModifiedBy = @userId,
            LastModifiedOn = GETDATE(),
            IpAddress = @IpAddress
        WHERE RoleId = @roleId;

        SET @Result = @roleId;
    END
END
GO

/* 5. role list (cached by the API as _RoleMaster_All) */
CREATE OR ALTER PROCEDURE dbo.S_GetRoleList
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        RoleId,
        RoleName,
        IsActive,
        ISNULL(rm.RoleIconId, 0) AS RoleIconId,
        (SELECT TOP 1 name FROM UserMaster um WHERE um.id = rm.CreatedBy) AS CreatedBy,
        FORMAT(rm.CreatedOn, 'dd-MM-yyyy hh:mm tt') AS CreatedOn,
        (SELECT TOP 1 name FROM UserMaster um WHERE um.id = rm.LastModifiedBy) AS LastModifiedBy,
        FORMAT(rm.LastModifiedOn, 'dd-MM-yyyy hh:mm tt') AS LastModifiedOn
    FROM RoleMaster rm
    ORDER BY RoleName;
END
GO

/* 6. roles of a user */
CREATE OR ALTER PROCEDURE dbo.S_GetUserRoles
(
    @branchId int,
    @userId   int
)
AS
BEGIN
    SELECT
        UR.RoleId, RM.RoleName,
        ISNULL(rm.RoleIconId, 0) AS RoleIconId,
        ISNULL((SELECT TOP 1 1 FROM UserWisefavoriteRoleMapping FRM
                WHERE FRM.BranchId = @branchId AND FRM.UserId = @userId AND FRM.RoleId = rm.RoleId), '0') AS isFavoriteRole
    FROM UserRoleMapping UR
    INNER JOIN RoleMaster RM ON UR.RoleId = RM.RoleId AND UR.IsActive = 1 AND RM.IsActive = 1
    WHERE UR.UserId = @userId AND ur.TypeId = 1 AND UR.BranchId = @branchId
    ORDER BY RM.RoleName;
END
GO

/* 7. Role Master grid card shows the role icon: the saved page config read "imagePath" */
UPDATE dbo.PageConfigMaster
SET ConfigJson = REPLACE(ConfigJson, N'"imagePath"', N'"roleIcon"'),
    LastModifiedOn = GETDATE()
WHERE ConfigKey = N'roleMaster'
  AND ConfigJson LIKE N'%"imagePath"%';
GO

/* 8. RoleMaster.FaIconId is no longer used (procedures above no longer read it) */
IF COL_LENGTH('dbo.RoleMaster', 'FaIconId') IS NOT NULL
BEGIN
    DECLARE @df sysname = (SELECT dc.name FROM sys.default_constraints dc
                           INNER JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id
                           WHERE dc.parent_object_id = OBJECT_ID('dbo.RoleMaster') AND c.name = 'FaIconId');
    IF @df IS NOT NULL EXEC (N'ALTER TABLE dbo.RoleMaster DROP CONSTRAINT ' + @df);
    ALTER TABLE dbo.RoleMaster DROP COLUMN FaIconId;
END
GO
